import React, { useState, useEffect } from 'react';
import {
  Modal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Row,
  Col,
  Input,
  Label,
  FormGroup,
  // CustomInput
} from 'reactstrap';
import moment from 'moment';
import validator from 'validator';
// import Select from 'react-select';
import DatePicker from 'react-datepicker';
import CustomButton from '../../../../components/CustomButton';
import CustomCheckbox from '../../../../components/CustomCheckbox';
import { formResMessage } from 'utils/commonFunc';
// import { handleKeyNumberPress, handleKeyCharacterPress } from 'utils/commonFunc';

const SchoolAdminFormModal = ({
  isModalOpen,
  // schools,
  saveSchoolAdmin,
  updateSchoolAdmin,
  schoolAdminUpdateSuccess,
  formModalCloseProp,
  schoolAdmin,
}) => {
  const stateObj = {
    data: {
      schoolAdminId: null,
      name: '',
      email: '',
      gender: '',
      dateOfBirth: '',
      qualification: '',
      joiningDateTime: '',
      designation: '',
      department: '',
      totalExperience: '',
      status: 'ACTIVE',
    },
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);

  // useEffect(() => {
  //   if(schools && schools.length > 0) {
  //     let schoolArr = [];
  //     schools.forEach(item => {
  //       schoolArr.push({
  //         schoolId: item.schoolId,
  //         label: `${item.schoolCode} - ${item.schoolName}`,
  //         value: item.schoolId
  //       });
  //     });
  //     setState(prevState => ({ ...prevState, schoolArr: schoolArr }));
  //   }
  // },[schools]);

  useEffect(() => {
    if (schoolAdmin && Object.keys(schoolAdmin).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          ...prevState?.data,
          schoolAdminId: schoolAdmin.schoolAdminId,
          name: schoolAdmin.name,
          email: schoolAdmin.email,
          gender: schoolAdmin.gender,
          dateOfBirth: schoolAdmin.dateOfBirth,
          qualification: schoolAdmin.qualification,
          joiningDateTime: schoolAdmin.joiningDateTime,
          designation: schoolAdmin.designation,
          department: schoolAdmin.department,
          totalExperience: schoolAdmin.totalExperience,
        },
      }));
    }
  }, [schoolAdmin]);

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const handleCheckChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.id },
    }));
  };

  // const handleSelectChange = (name, selectItem) => {
  //   setState(prevState => ({
  //     ...prevState,
  //     data: {
  //       ...prevState.data,
  //       [name]: selectItem,
  //     }
  //   }));
  // }

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf() },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (Object.keys(errors).length === 0) {
      setState(prevState => ({ ...prevState, loading: true }));
      if (data.schoolAdminId) {
        return updateSchoolAdmin(data)
          .then(() => {
            stateValReset();
            schoolAdminUpdateSuccess('update');
          })
          .catch(err => setError(err));
      }
      return saveSchoolAdmin(data)
        .then(() => {
          stateValReset();
          schoolAdminUpdateSuccess('add');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (validator.isEmpty(data.name)) {
      errors.name = 'Name cannot be empty';
    }
    if (validator.isEmpty(data.email)) {
      errors.email = 'Email cannot be empty';
    } else if (!validator.isEmail(data.email)) {
      errors.email = 'Invalid email';
    }
    if (validator.isEmpty(data.gender)) {
      errors.gender = 'Gender cannot be empty';
    }
    if (validator.isEmpty(data.dateOfBirth.toString())) {
      errors.dateOfBirth = 'Date of birth cannot be empty';
    } else if (moment(data.dateOfBirth) > moment().subtract(21, 'years')) {
      errors.dateOfBirth = 'Invalid date of birth, Minimum age should be 21';
    }
    if (validator.isEmpty(data.qualification)) {
      errors.qualification = 'Qualification cannot be empty';
    }
    if (validator.isEmpty(data.joiningDateTime.toString())) {
      errors.joiningDateTime = 'Joining date cannot be empty';
    } else if (data.dateOfBirth >= data.joiningDateTime) {
      errors.joiningDateTime = "Joining date shouldn't be less than or equal to the Date of birth";
    }
    if (validator.isEmpty(data.designation)) {
      errors.designation = 'Designation type cannot be empty';
    }
    if (validator.isEmpty(data.department)) {
      errors.department = 'Department type cannot be empty';
    }
    if (validator.isEmpty(data.totalExperience)) {
      errors.totalExperience = 'Total experience cannot be empty';
    }
    return errors;
  };

  const { data, errors, loading } = stateVal;
  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.schoolAdminId ? 'UPDATE ADMIN' : 'ADD ADMIN'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              {/* <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">Select school<sup> *</sup></Label>
                        <Select
                          value={data.school.schoolId ? { label: data.school.label, value: data.school.value } : null}
                          onChange={(value) => handleSelectChange('school', value)}
                          options={schoolArr}
                        />
                        {errors.schoolId && <span className="err-msg">{errors.schoolId}</span>}
                      </FormGroup>
                  </Col>
                  </Row> */}
              <Row>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="name"
                      onChange={e => handleChange(e)}
                      value={data.name}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.name && <span className="err-msg">{errors.name}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Email<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="email"
                      onChange={e => handleChange(e)}
                      value={data.email}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.email && <span className="err-msg">{errors.email}</span>}
                  </FormGroup>
                  <FormGroup style={{ marginTop: 15, marginBottom: 20 }}>
                    <Label for="exampleCheckbox">
                      Gender<sup> *</sup>
                    </Label>
                    <Row>
                      <Col sm={3}>
                        <CustomCheckbox
                          value={data.gender}
                          id="MALE"
                          name="gender"
                          label="Male"
                          onChange={handleCheckChange}
                          checked={data.gender === 'MALE'}
                        />
                      </Col>
                      <Col sm={3}>
                        <CustomCheckbox
                          value={data.gender}
                          id="FEMALE"
                          name="gender"
                          label="Female"
                          onChange={handleCheckChange}
                          checked={data.gender === 'FEMALE'}
                        />
                      </Col>
                    </Row>
                    {errors.gender && <span className="err-msg">{errors.gender}</span>}
                  </FormGroup>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Date of Birth<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.dateOfBirth ? new Date(data.dateOfBirth) : null}
                      onChange={value => handleDateChange('dateOfBirth', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                    />
                    {errors.dateOfBirth && <span className="err-msg">{errors.dateOfBirth}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Qualification<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="qualification"
                      onChange={handleChange}
                      value={data.qualification}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.qualification && <span className="err-msg">{errors.qualification}</span>}
                  </FormGroup>
                </Col>

                <Col sm={6}>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Joining date<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.joiningDateTime ? new Date(data.joiningDateTime) : null}
                      onChange={value => handleDateChange('joiningDateTime', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                    />
                    {errors.joiningDateTime && <span className="err-msg">{errors.joiningDateTime}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Designation<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="designation"
                      onChange={handleChange}
                      value={data.designation}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.designation && <span className="err-msg">{errors.designation}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Department<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="department"
                      onChange={handleChange}
                      value={data.department}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.department && <span className="err-msg">{errors.department}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Total experience<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="totalExperience"
                      onChange={handleChange}
                      value={data.totalExperience}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.totalExperience && <span className="err-msg">{errors.totalExperience}</span>}
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            type="submit"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="secondary"
            disabled={loading}
            loading={loading}
          />
          <CustomButton
            className="ml-2"
            type="reset"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="default"
            onClick={formModalClose}
            disabled={loading}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default SchoolAdminFormModal;
