import React from 'react';
import ListDropDown from '../../Common/ListDropDown';

const SchoolAdminList = ({ adminItem, fetchSchoolAdmin, deleteSchoolAdmin }) => {
  return (
    <tr>
      <td>{`${adminItem.school.schoolCode} - ${adminItem.school.schoolName}`}</td>
      <td>{adminItem.name}</td>
      <td>{adminItem.email}</td>
      <td>{adminItem.gender}</td>
      <td>{adminItem.designation}</td>
      <td className="text-center">
        <ListDropDown
          actionList={['edit', 'delete']}
          item={adminItem}
          fetchItem={() => fetchSchoolAdmin(adminItem.schoolAdminId)}
          deleteItem={() => deleteSchoolAdmin(adminItem.schoolAdminId)}
        />
      </td>
    </tr>
  );
};

export default SchoolAdminList;
