import React from 'react';
import { connect } from 'react-redux';
import { Card, CardBody, Table, Row, Col } from 'reactstrap';
import { schoolAdminTableHead } from 'variables/general';
import {
  fetchAllSchoolAdminsService,
  saveSchoolAdminService,
  fetchSchoolAdminService,
  updateSchoolAdminService,
  deleteSchoolAdminService,
} from 'actions/admin/schoolAdmins';
import SchoolAdminList from './components/SchoolAdminList.jsx';
import SchoolAdminFormModal from './components/SchoolAdminFormModal.jsx';
import Page from '../Common/Pagination.jsx';
import { getGlobalSchoolUtils } from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast } from '../../../actions/admin/auth.js';
import CustomButton from '../../../components/CustomButton.jsx';

class SchoolAdminPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
    };
  }

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId });
      this.fetchAllSchoolAdmins();
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  fetchAllSchoolAdmins = () => {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool?.schoolId) {
      this.props.fetchAllSchoolAdmins({
        schoolId: globalSchool?.schoolId,
        token: this.props.loggedUserToken,
        pageParams: this.state.pageParams,
      });
    }
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  saveSchoolAdmin = data => {
    data.school = { schoolId: this.state.schoolId };
    return this.props.saveSchoolAdmin({ postData: data, token: this.props.loggedUserToken });
  };

  fetchSchoolAdmin = schoolAdminId => {
    return this.props
      .fetchSchoolAdmin({ schoolAdminId, token: this.props.loggedUserToken })
      .then(() => this.formModalOpen());
  };

  updateSchoolAdmin = data => {
    data.school = { schoolId: this.state.schoolId };
    return this.props.updateSchoolAdmin({
      schoolAdminId: data.schoolAdminId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  schoolAdminUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Admin added successfully' : 'Admin Updated successfully', 'success');
    this.fetchAllSchoolAdmins();
  };

  deleteSchoolAdmin = schoolAdminId => {
    return this.props.deleteSchoolAdmin({ schoolAdminId, token: this.props.loggedUserToken }).then(() => {
      // this.deleteCancel();
      this.fetchAllSchoolAdmins();
    });
  };

  fetchPageData = page => {
    this.setState(
      {
        pageParams: {
          ...this.state.pageParams,
          page,
        },
      },
      () => {
        // window.scrosllTo(0, this.topRef.current.offsetTop)
        // let wHeight = window.innerHeight;
        // window.scrollY = wHeight;
        this.fetchAllSchoolAdmins();
      }
    );
  };

  render() {
    const { isModalOpen } = this.state;
    const { schoolAdminData, schools, schoolAdmin } = this.props;
    const noDataFoundDiv = (
      <tr className="text-center">
        <td colSpan="7" style={{ paddingTop: 30, fontWeight: 'bold' }}>
          NO DATA FOUND
        </td>
      </tr>
    );
    return (
      <div className="content">
        <Row className="mb-3">
          <Col>
            <CustomButton
              style={{ float: 'right' }}
              variant="contained"
              color="secondary"
              onClick={this.formModalOpen}
              name="Add Admin"
            />
          </Col>
        </Row>
        <Row>
          <Col xs={12}>
            <Card>
              <CardBody>
                <Table size="sm" responsive>
                  <thead className="text-primary">
                    <tr>
                      {schoolAdminTableHead.map((prop, key) => {
                        if (key === schoolAdminTableHead.length - 1)
                          return (
                            <th key={key} className="text-center">
                              {prop}
                            </th>
                          );
                        return <th key={key}>{prop}</th>;
                      })}
                    </tr>
                  </thead>
                  <tbody>
                    {schoolAdminData?.content?.length > 0
                      ? schoolAdminData.content.map(adminItem => {
                          return (
                            <SchoolAdminList
                              key={adminItem.schoolAdminId}
                              adminItem={adminItem}
                              fetchSchoolAdmin={this.fetchSchoolAdmin}
                              deleteSchoolAdmin={this.deleteSchoolAdmin}
                            />
                          );
                        })
                      : noDataFoundDiv}
                  </tbody>
                </Table>
                <hr />
                {schoolAdminData?.content?.length > 0 ? (
                  <Page {...schoolAdminData} fetchPageData={this.fetchPageData} />
                ) : null}
              </CardBody>
            </Card>
          </Col>
        </Row>
        <SchoolAdminFormModal
          isModalOpen={isModalOpen}
          schools={schools}
          formModalCloseProp={this.formModalClose}
          saveSchoolAdmin={this.saveSchoolAdmin}
          schoolAdmin={schoolAdmin}
          updateSchoolAdmin={this.updateSchoolAdmin}
          schoolAdminUpdateSuccess={this.schoolAdminUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    schools: state.schools.schoolList,
    schoolAdminData: state.schoolAdmins.schoolAdminData,
    schoolAdmin: state.schoolAdmins.schoolAdmin,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllSchoolAdmins: data => dispatch(fetchAllSchoolAdminsService(data)),
    saveSchoolAdmin: data => dispatch(saveSchoolAdminService(data)),
    fetchSchoolAdmin: data => dispatch(fetchSchoolAdminService(data)),
    updateSchoolAdmin: data => dispatch(updateSchoolAdminService(data)),
    deleteSchoolAdmin: data => dispatch(deleteSchoolAdminService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(SchoolAdminPage);
